async function load(){try{const r=await fetch('/api/state',{cache:'no-store'});const j=await r.json();if(!r.ok)throw new Error(j.error||'State unavailable');render(j);}catch(e){console.error(e);markFinancialSnapshotUnavailable(`Financial snapshot unavailable: ${e.message}.`);msg(e.message,true);}}
async function patchSettingsVerified(data){
  // PATCH returns the committed settings card, not an operator-state snapshot.
  // Verify the acknowledgement before clearing drafts, then refresh the board.
  const reply=await patch('/api/settings',data);
  const suppliedState=reply?.state?.settings?reply.state:reply?.settings?reply:null;
  const committed=suppliedState?.settings||reply;
  const verify=(settings)=>{for(const [key,value] of Object.entries(data)){
    const actual=settings?.[key];
    const matches=typeof value==='boolean'?actual===value:
      typeof value==='number'?Number.isFinite(Number(actual))&&Number(actual)===value:
      String(actual??'')===String(value??'');
    if(!matches)throw new Error(`Setting ${key} did not persist exactly`);
  }};
  verify(committed);
  if(suppliedState){acknowledgeSavedDrafts(data);return suppliedState;}
  const response=await fetch('/api/state',{cache:'no-store'});
  if(!response.ok)throw new Error(`Settings saved, but dashboard refresh failed (HTTP ${response.status}).`);
  const fresh=await response.json();
  if(!fresh?.settings)throw new Error('Settings saved, but the dashboard response has no settings.');
  verify(fresh.settings);
  acknowledgeSavedDrafts(data);
  return fresh;
}
function bindBoard(id){const b=$(id);b.oninput=e=>{const i=e.target.closest('[data-setting-key]');if(i)drafts.set(i.dataset.settingKey,i.value);};b.onclick=async e=>{const save=e.target.closest('[data-model-save]');if(save){const row=save.closest('tr'),data={};for(const i of row.querySelectorAll('[data-setting-key]')){if(i.value.trim()===''||!i.checkValidity()){i.reportValidity();msg(`Invalid ${i.closest('label')?.firstChild?.textContent||i.dataset.settingKey}: ${i.validationMessage||'a value is required'}`,true);return;}data[i.dataset.settingKey]=Number(i.value);}save.disabled=true;try{const fresh=await patchSettingsVerified(data);render(fresh);msg(`${save.dataset.modelSave} settings saved.`);}catch(x){msg(x.message,true);}finally{save.disabled=false;}return;}const btn=e.target.closest('[data-model-key]');if(!btn)return;const key=btn.dataset.modelKey,enable=btn.dataset.enabled!=='true';btn.disabled=true;try{const fresh=await patchSettingsVerified({[key]:enable});render(fresh);msg(`${btn.dataset.modelName} ${enable?'enabled':'disabled'}.`);}catch(x){msg(x.message,true);}finally{btn.disabled=false;}};}
