function clock(){setText('madridClock',new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Madrid',weekday:'short',hour:'2-digit',minute:'2-digit',second:'2-digit',day:'2-digit',month:'short'}).format(new Date())+' Europe/Madrid');}
setInterval(clock,1000);clock();load();const es=new EventSource('/api/events');es.onmessage=e=>{try{scheduleRender(JSON.parse(e.data));}catch{}};es.onerror=()=>{setText('executionFinancialStatus','Update stream disconnected. Displayed values are the last received snapshot, not live totals.');};

